mapper.select:
			SELECT ID, CHECK_IN, CHECK_OUT, USER_NAME, USER_EMAIL, USER_PHONE
 			  FROM CAMP_RESERVATION_TBL
 			 WHERE USER_NAME=#{userName}
 			   AND USER_EMAIL=#{userEmail}
 			   AND USER_PHONE=#{userPhone}
 			   AND CHECK_IN=#{checkIn}
 			   AND CHECK_OUT=#{checkOut}

			SELECT ID, CAMP_ID, CAMP_C_NO, CAMP_NAME, CHECK_IN, CHECK_OUT, USER_NAME, USER_EMAIL, USER_PHONE
 			  FROM CAMP_RESERVATION_TBL
 			 WHERE USER_NAME = #{userName}
 			   AND USER_EMAIL = #{userEmail}
 			   AND USER_PHONE = #{userPhone}
 		     ORDER BY CHECK_IN

mapper.update:
		UPDATE CAMP_TOT_RESERVATION_TBL
   		   SET AVAIL_SITE = #{availSite}
 		 WHERE CAMP_ID = #{id}
